31	Stmt LowerNormalCopy(const CopyNode &op, const LowerArgs &lower_args,
32	                     arith::Analyzer *analyzer) {
33	  bool is_cpu_target = lower_args.target->GetTargetDeviceType() == kDLCPU;
34	  auto simt_loop = op.MakeSIMTLoop(analyzer);
35	  auto fused_loop = Downcast<For>(ParallelLoopFuser::Fuse(simt_loop));
36	
37	  For vectorized_thread_loop;
38	  auto par_op = ParallelOp(fused_loop);
39	
40	  if (is_cpu_target || IsLocalBuffer(op.src) || IsLocalBuffer(op.dst)) {
41	    if (IsLocalBuffer(op.src) && !IsLocalBuffer(op.dst)) {
42	      // A conflict write only occurs when multiple threads write to the same
43	      // global address. If any dst_range dimension's min depends on the thread
44	      // variable, each thread targets a distinct location and there is no
45	      // conflict.
46	      bool dst_depends_on_thread = false;
47	      for (const auto &range : op.dst_range) {
48	        if (tirx::UsesVar(range->min, [&](const VarNode *v) {
49	              return v == lower_args.thread_var.get();
50	            })) {
51	          dst_depends_on_thread = true;
52	          break;
53	        }
54	      }
55	      if (!dst_depends_on_thread) {
56	        DLOG(WARNING) << "Copy from local buffer `" << op.src->name << "` to "
57	                      << op.dst.scope() << " buffer `" << op.dst->name
58	                      << "` may cause conflicted write.";
59	      }
60	    }
61	    vectorized_thread_loop = VectorizeLoop(fused_loop, lower_args.layout_map);
62	    return vectorized_thread_loop;
63	  }
64	
65	  std::vector<InferLevel> levels = {InferLevel::kCommon, InferLevel::kStrict,
66	                                    InferLevel::kFree};
67	  for (auto level : levels) {
68	    par_op->InferLayout({lower_args.target,
69	                         lower_args.thread_bounds,
70	                         lower_args.layout_map,
71	                         analyzer,
72	                         false,
73	                         lower_args.buffer_remap,
74	                         {}},
75	                        level);
76	  }
77	  auto loop_layout = par_op->GetLoopLayout();
78	  return LowerParallelLoop(
79	      par_op->GetRoot(), loop_layout, lower_args.thread_var, analyzer,
80	      lower_args.layout_map, par_op->GetPredicate(lower_args.thread_var),
81	      /*parallel_loop=*/true, /*should_vectorize=*/true,
82	      par_op->LoopLayoutRequiresPaddingGuard());
83	}
