92	const CopyImpl &ResolveCopyImpl(Target target) {
93	  const auto &registry = CopyImplRegistry();
94	  const CopyImpl *best_impl = nullptr;
95	  int best_priority = std::numeric_limits<int>::min();
96	  for (const CopyImpl &impl : registry) {
97	    if (impl.match_target(target) && impl.priority >= best_priority) {
98	      best_impl = &impl;
99	      best_priority = impl.priority;
100	    }
101	  }
102	  ICHECK(best_impl != nullptr)
103	      << "tl.copy requires a target-specific implementation, but no copy "
104	         "implementation is registered for "
105	      << target->str();
106	  return *best_impl;
107	}
