150	Stmt LowerIm2ColSIMT(const Im2ColOpNode &op, const LowerArgs &lower_args,
151	                     arith::Analyzer *analyzer) {
152	  const Buffer &src = op.src_;
153	  const Buffer &dst = op.dst_;
154	  const BufferRegion &dst_region = op.dstRegion_;
155	
156	  ICHECK(src->shape.size() == 4);
157	  ICHECK(src->dtype == dst->dtype);
158	
159	  size_t ndim = dst_region->region.size();
160	  ICHECK(ndim >= 2) << "im2col dstRegion must have at least 2 dims";
161	
162	  PrimExpr block_m = dst_region->region[ndim - 2]->extent;
163	  PrimExpr block_k = dst_region->region[ndim - 1]->extent;
164	  Var i("i", block_m.dtype());
165	  Var j("j", block_k.dtype());
166	  analyzer->Bind(i, Range::FromMinExtent(make_zero(i.dtype()), block_m));
167	  analyzer->Bind(j, Range::FromMinExtent(make_zero(j.dtype()), block_k));
168	
169	  PrimExpr h_dim = src->shape[1];
170	  PrimExpr w_dim = src->shape[2];
171	  PrimExpr c_dim = src->shape[3];
172	  PrimExpr out_h =
173	      FloorDiv(h_dim + 2 * op.padding_ - (op.kernel_ - 1) * op.dilation_ - 1,
174	               op.stride_) +
175	      1;
176	  PrimExpr out_w =
177	      FloorDiv(w_dim + 2 * op.padding_ - (op.kernel_ - 1) * op.dilation_ - 1,
178	               op.stride_) +
179	      1;
180	  PrimExpr out_hw = out_h * out_w;
181	
182	  PrimExpr k = op.c_step_ * block_k + j;
183	  PrimExpr m = op.nhw_step_ * block_m + i;
184	  PrimExpr access_h = FloorDiv(FloorMod(m, out_hw), out_w) * op.stride_ +
185	                      FloorDiv(k, op.kernel_ * c_dim) * op.dilation_ -
186	                      op.padding_;
187	  PrimExpr access_w = FloorMod(m, out_w) * op.stride_ +
188	                      FloorMod(FloorDiv(k, c_dim), op.kernel_) * op.dilation_ -
189	                      op.padding_;
190	
191	  PrimExpr in_bound = And(And(access_h >= make_zero(access_h.dtype()),
192	                              access_w >= make_zero(access_w.dtype())),
193	                          And(access_h < h_dim, access_w < w_dim));
194	
195	  PrimExpr value = BufferLoad(
196	      src, {FloorDiv(m, out_hw), access_h, access_w, FloorMod(k, c_dim)});
197	  value = if_then_else(in_bound, value, make_zero(dst->dtype));
198	
199	  Array<PrimExpr> dst_indices;
200	  dst_indices.reserve(ndim);
201	  for (size_t dim = 0; dim < ndim; ++dim) {
202	    const Range &range = dst_region->region[dim];
203	    if (dim == ndim - 2) {
204	      dst_indices.push_back(range->min + i);
205	    } else if (dim == ndim - 1) {
206	      dst_indices.push_back(range->min + j);
207	    } else {
208	      dst_indices.push_back(range->min);
209	    }
210	  }
211	
212	  Stmt body = BufferStore(dst, value, dst_indices);
213	  body = For(j, make_zero(j.dtype()), block_k, ForKind::kParallel, body);
214	  body = For(i, make_zero(i.dtype()), block_m, ForKind::kParallel, body);
215	
216	  auto fused_loop = Downcast<For>(ParallelLoopFuser::Fuse(Downcast<For>(body)));
217	  auto par_op = ParallelOp(fused_loop);
218	  std::vector<InferLevel> levels = {InferLevel::kCommon, InferLevel::kStrict,
219	                                    InferLevel::kFree};
220	  for (auto level : levels) {
221	    par_op->InferLayout({lower_args.target,
222	                         lower_args.thread_bounds,
223	                         lower_args.layout_map,
224	                         analyzer,
225	                         false,
226	                         lower_args.buffer_remap,
227	                         {}},
228	                        level);
229	  }
230	  auto loop_layout = par_op->GetLoopLayout();
231	  return LowerParallelLoop(
232	      par_op->GetRoot(), loop_layout, lower_args.thread_var, analyzer,
233	      lower_args.layout_map, par_op->GetPredicate(lower_args.thread_var),
234	      /*parallel_loop=*/true, /*should_vectorize=*/true,
235	      par_op->LoopLayoutRequiresPaddingGuard());
236	}
