267	// Constructs a Copy operator node from call arguments and annotations.
268	// args[0]: source region, args[1]: destination region
269	// annotations: Map containing common SIMT hints and backend-specific metadata.
270	Copy::Copy(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
271	  ObjectPtr<CopyNode> node = make_object<CopyNode>();
272	  auto src_access = NormalizeToAccessRegion(args[0], kAccessRead);
273	  auto dst_access = NormalizeToAccessRegion(args[1], kAccessWrite);
274	  node->src = src_access.region->buffer;
275	  node->dst = dst_access.region->buffer;
276	  node->src_range = src_access.region->region;
277	  node->dst_range = dst_access.region->region;
278	  node->SetAccessRegions({src_access, dst_access});
279	  // Copy annotations from the Call node
280	  node->annotations = annotations;
281	  if (auto dst_block = node->annotations.Get("dst_block")) {
282	    if (auto int_imm = dst_block->as<IntImmNode>()) {
283	      if (int_imm->value != -1) {
284	        node->dst_block = Integer(int_imm->value);
285	      }
286	    } else {
287	      node->dst_block = Downcast<PrimExpr>(dst_block.value());
288	    }
289	  }
290	  data_ = std::move(node);
291	}
