293	// Creates a shallow clone of this CopyNode.
294	TileOperator CopyNode::Clone() const {
295	  auto op = make_object<CopyNode>(*this);
296	  if (par_op_.defined()) {
297	    op->par_op_ = Downcast<ParallelOp>(par_op_->Clone());
298	  }
299	  return Copy(op);
