302	// Creates iterator variables for dimensions with extent > 1.
303	Array<IterVar> CopyNode::MakeIterVars() const {
304	  // Choose the range set from the lowest-level memory scope between src and
305	  // dst. Scope levels: global < shared/shared.dyn/shared.tmem < local.fragment
306	  // (fragment)
307	  auto scope_level = [](const Buffer &b) -> int {
308	    String s = b.scope();
309	    if (s == "local.fragment" || s == "local")
310	      return 2;
311	    if (s == "shared" || s == "shared.dyn" || s == "shared.tmem")
312	      return 1;
313	    // default to global level for unknown scopes
314	    return 0;
315	  };
316	
317	  int src_level = scope_level(src);
318	  int dst_level = scope_level(dst);
319	  bool base_is_src = (src_level >= dst_level);
320	  const Array<Range> &base_ranges = base_is_src ? src_range : dst_range;
321	
322	  // Sanity check: when switching away from the original (src_range),
323	  // ensure the chosen base ranges are not provably smaller than the original
324	  // per dimension. This guards against generating undersized loop domains.
325	  // Improved logic: use two pointers to traverse both base_ranges and
326	  // src_range, skipping dimensions with extent == 1. The number of non-1
327	  // extents must match.
328	  arith::Analyzer analyzer;
329	
330	  size_t base_dim = 0, src_dim = 0;
331	  while (base_dim < base_ranges.size() && src_dim < src_range.size()) {
332	    // Skip base extents that are 1
333	    while (base_dim < base_ranges.size() &&
334	           is_one(base_ranges[base_dim]->extent)) {
335	      ++base_dim;
336	    }
337	    // Skip src extents that are 1
338	    while (src_dim < src_range.size() && is_one(src_range[src_dim]->extent)) {
339	      ++src_dim;
340	    }
341	    // Both indices now at non-1, or at end
342	    if (base_dim < base_ranges.size() && src_dim < src_range.size()) {
343	      PrimExpr base_ext = base_ranges[base_dim]->extent;
344	      PrimExpr src_ext = src_range[src_dim]->extent;
345	      // Only fail if base extent is provably smaller than src extent
346	      if (analyzer.CanProve(base_ext < src_ext)) {
347	        std::ostringstream oss;
348	        oss << "Selected loop range is smaller than original src range at "
349	               "matched non-1 dimension: "
350	            << "base(extent=" << base_ext
351	            << ", scope=" << (base_is_src ? src.scope() : dst.scope())
352	            << ", min=" << base_ranges[base_dim]->min
353	            << ", base_dim=" << base_dim << ") < src(extent=" << src_ext
354	            << ", min=" << src_range[src_dim]->min << ", src_dim=" << src_dim
355	            << ", scope=" << src.scope() << ") for src=" << src->name
356	            << ", dst=" << dst->name << "\n";
357	        oss << "src buffer: " << src->name << ", scope=" << src.scope() << "\n";
358	        oss << "dst buffer: " << dst->name << ", scope=" << dst.scope() << "\n";
359	        oss << "base_ranges[" << base_dim
360	            << "]: min=" << base_ranges[base_dim]->min
361	            << ", extent=" << base_ext << "\n";
362	        oss << "src_ranges[" << src_dim << "]: min=" << src_range[src_dim]->min
363	            << ", extent=" << src_ext << "\n";
364	        LOG(FATAL) << oss.str();
365	      }
366	      ++base_dim;
367	      ++src_dim;
368	    }
369	  }
370	
371	  // Any remaining unmatched dimensions in either range must all have extent ==
372	  // 1
373	  while (base_dim < base_ranges.size()) {
374	    ICHECK(is_one(base_ranges[base_dim]->extent))
375	        << "base_ranges has extra non-1 extent at dim " << base_dim;
376	    ++base_dim;
377	  }
378	  while (src_dim < src_range.size()) {
379	    ICHECK(is_one(src_range[src_dim]->extent))
380	        << "src_range has extra non-1 extent at dim " << src_dim;
381	    ++src_dim;
382	  }
383	
384	  Array<IterVar> loop_vars;
385	  size_t idx = 0;
386	  for (size_t i = 0; i < base_ranges.size(); i++) {
387	    if (is_one(base_ranges[i]->extent))
388	      continue;
389	    Var var = Var(std::string{char('i' + idx)}, base_ranges[i]->extent->dtype);
390	    idx++;
391	    loop_vars.push_back(
392	        {Range(0, base_ranges[i]->extent), var, IterVarType::kDataPar});
393	  }
394	  return loop_vars;
395	}
396	
397	// Generates index expressions for accessing src (src_dst=0) or dst (src_dst=1)
398	// buffers.
399	Array<PrimExpr> CopyNode::MakeIndices(const Array<IterVar> &ivs,
400	                                      int src_dst) const {
401	  Array<PrimExpr> indices;
402	  Array<Range> ranges = src_dst == 0 ? src_range : dst_range;
403	  size_t idx = 0;
404	  for (size_t i = 0; i < ranges.size(); i++) {
405	    if (is_one(ranges[i]->extent))
406	      indices.push_back(ranges[i]->min);
407	    else {
408	      indices.push_back(ranges[i]->min + ivs[idx]->var);
409	      idx++;
410	    }
411	  }
412	  ICHECK(idx == ivs.size())
413	      << "idx = " << idx << ", ivs.size() = " << ivs.size()
414	      << "src name = " << src->name << ", dst name = " << dst->name;
415	  return indices;
416	}
417	
418	// Builds a boundary predicate for memory accesses.
419	// Returns a conjunction of bounds checks, or empty PrimExpr if all checks pass.
420	PrimExpr CopyNode::MakePredicate(arith::Analyzer *analyzer,
421	                                 const Array<IterVar> &ivs,
422	                                 Array<PrimExpr> extents, int src_dst) const {
423	  Array<Range> ranges = src_dst == 0 ? src_range : dst_range;
424	
425	  Array<PrimExpr> cond_list;
426	  ICHECK(extents.size() == ranges.size()) << extents << " " << ranges;
427	  size_t idx = 0;
428	  for (size_t i = 0; i < ranges.size(); i++) {
429	    if (is_one(ranges[i]->extent))
430	      continue;
431	    PrimExpr cond = ranges[i]->min + ivs[idx]->var < extents[i];
432	    if (!analyzer->CanProve(cond, arith::ProofStrength::kSymbolicBound)) {
433	      cond_list.push_back(cond);
434	    }
435	    cond = ranges[i]->min + ivs[idx]->var >= 0;
436	    if (!analyzer->CanProve(cond, arith::ProofStrength::kSymbolicBound)) {
437	      cond_list.push_back(cond);
438	    }
439	    idx++;
440	  }
441	  if (cond_list.empty())
442	    return {};
443	  else {
444	    PrimExpr cond = cond_list[0];
445	    for (size_t i = 1; i < cond_list.size(); i++)
446	      cond = And(cond, cond_list[i]);
447	    return cond;
448	  }
449	}
