451	// Constructs a SIMT-style nested loop that implements the copy.
452	For CopyNode::MakeSIMTLoop(arith::Analyzer *analyzer) const {
453	  if (IsFP4UnpackLoad(src, dst)) {
454	    LOG(FATAL) << "SIMT copy from packed global float4_e2m1fn to unpacked "
455	               << "shared float4_e2m1_unpacked is not supported; use "
456	               << "T.tma_copy() for FP4 unpack loads (src=" << src->name
457	               << ", dst=" << dst->name << ").";
458	  }
459	
460	  Array<IterVar> loop_vars = MakeIterVars();
461	  bool is_scalar = loop_vars.empty();
462	
463	  for (const auto &iv : loop_vars)
464	    analyzer->Bind(iv->var, iv->dom);
465	  ICHECK(loop_vars.size() <= src_range.size())
466	      << "loop_vars.size() = " << loop_vars.size()
467	      << ", src_range.size() = " << src_range.size() << ", src = " << src->name
468	      << ", dst = " << dst->name;
469	
470	  ICHECK(loop_vars.size() <= dst_range.size())
471	      << "loop_vars.size() = " << loop_vars.size()
472	      << ", dst_range.size() = " << dst_range.size() << ", src = " << src->name
473	      << ", dst = " << dst->name;
474	
475	  Array<PrimExpr> src_indices = MakeIndices(loop_vars, 0);
476	  Array<PrimExpr> dst_indices = MakeIndices(loop_vars, 1);
477	
478	  PrimExpr src_predicate = MakePredicate(analyzer, loop_vars, src->shape, 0);
479	  PrimExpr dst_predicate = MakePredicate(analyzer, loop_vars, dst->shape, 1);
480	
481	  PrimExpr value = BufferLoad(src, src_indices);
482	  if (src->dtype != dst->dtype)
483	    value = Cast(dst->dtype, value);
484	  if (src_predicate.defined())
485	    value = if_then_else(src_predicate, value, make_zero(dst->dtype));
486	
487	  Stmt body = BufferStore(dst, value, dst_indices);
488	  if (dst_predicate.defined())
489	    body = IfThenElse(dst_predicate, body);
490	  if (is_scalar) {
491	    return For(Var("i"), 0, 1, ForKind::kSerial, body);
492	  }
493	
494	  for (int i = loop_vars.size() - 1; i >= 0; i--) {
495	    Map<String, ObjectRef> loop_annotations;
496	
497	    // Only attach the parallel related annotations on the outermost loop (i ==
498	    // 0)
499	    if (i == 0) {
500	      if (annotations.count(attr::kCoalescedWidth)) {
501	        loop_annotations.Set(attr::kCoalescedWidth,
502	                             annotations.Get(attr::kCoalescedWidth).value());
503	      }
504	      if (annotations.count(attr::kParallelLoopLayout)) {
505	        loop_annotations.Set(
506	            attr::kParallelLoopLayout,
507	            annotations.Get(attr::kParallelLoopLayout).value());
508	      }
509	    }
510	
511	    body = For(loop_vars[i]->var, 0, loop_vars[i]->dom->extent,
512	               ForKind::kParallel, body, std::nullopt, loop_annotations);
513	  }
514	  return Downcast<For>(body);
515	}
516	
517	LayoutMap CopyNode::InferLayout(const LayoutInferArgs &layout_args,
518	                                InferLevel level) const {
519	  return InferCopyLayout(*this, layout_args, level);
520	}
521	
522	LayoutMap CopyNode::InferSIMTLayout(const LayoutInferArgs &layout_args,
523	                                    InferLevel level) const {
524	  if (!par_op_.defined()) {
525	    arith::Analyzer analyzer;
526	    par_op_ = ParallelOp(MakeSIMTLoop(&analyzer));
527	  }
528	  return par_op_->InferLayout(layout_args, level);
529	}
530	// Lowers the copy operation by dispatching to the selected target
531	// implementation.
532	Stmt CopyNode::Lower(const LowerArgs &lower_args,
533	                     arith::Analyzer *analyzer) const {
534	  return LowerCopyForTarget(*this, lower_args, analyzer);
535	}
536	
537	// Constructs an Im2ColOp node from call arguments.
538	// args: src, dst, nhw_step, c_step, kernel, stride, dilation, padding,
539	// eviction_policy
540	Im2ColOp::Im2ColOp(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
541	  ObjectPtr<Im2ColOpNode> node = make_object<Im2ColOpNode>();
542	  auto src_access = NormalizeToAccessRegion(args[0], kAccessRead);
543	  auto dst_access = NormalizeToAccessRegion(args[1], kAccessWrite);
544	  node->srcRegion_ = src_access.region;
545	  node->dstRegion_ = dst_access.region;
546	  node->SetAccessRegions({src_access, dst_access});
547	  node->src_ = node->srcRegion_->buffer;
548	  node->dst_ = node->dstRegion_->buffer;
549	  node->nhw_step_ = args[2];
550	  node->c_step_ = args[3];
551	  node->kernel_ = args[4].as<IntImm>().value()->value;
552	  node->stride_ = args[5].as<IntImm>().value()->value;
553	  node->dilation_ = args[6].as<IntImm>().value()->value;
554	  node->padding_ = args[7].as<IntImm>().value()->value;
555	  node->eviction_policy_ = args[8].as<IntImm>().value()->value;
556	  node->annotations_ = annotations;
557	  data_ = std::move(node);
558	}
559	
560	// Creates a shallow copy of this Im2ColOpNode.
561	TileOperator Im2ColOpNode::Clone() const {
562	  auto op = make_object<Im2ColOpNode>(*this);
563	  return Im2ColOp(op);
564	}
565	
566	Stmt Im2ColOpNode::Lower(const LowerArgs &lower_args,
567	                         arith::Analyzer *analyzer) const {
568	  return LowerIm2ColForTarget(*this, lower_args, analyzer);
569	}
570	
571	// Register the Copy operation with TVM's TIR system
572	// This makes the copy operation available for use in TVM programs
573	// - Takes 5 inputs: src_buffer, dst_buffer, and annotation-driven options.
574	// - Marked as opaque since it has side effects (memory writes)
575	TIR_REGISTER_TL_TILE_OP(Copy, copy)
576	    .set_num_inputs(5)
577	    .set_attr<TCallEffectKind>("TCallEffectKind",
578	                               Integer(CallEffectKind::kOpaque));
579	
