581	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "async_copy")
582	    .set_attr<OpBuilderFunc>("TLOpBuilder",
583	                             [](Array<PrimExpr> args,
584	                                Map<String, ObjectRef> annotations) {
585	                               Map<String, ObjectRef> ann = annotations;
586	                               ann.Set("is_async_copy",
587	                                       IntImm(DataType::Int(32), 1));
