610	// Register the maca_async_copy operation - for MACA async copy using
611	// memcpy_async and barrier_arrive_and_wait.
612	TVM_REGISTER_OP("tl.tileop.maca_async_copy")
613	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "maca_async_copy")
614	    .set_attr<OpBuilderFunc>("TLOpBuilder",
