58	  PrimExpr elements_i64 = cast(DataType::Int(64), elements);
59	  if (bits % 8 == 0) {
60	    return elements_i64 * IntImm(DataType::Int(64), bits / 8);
61	  }
62	  return FloorDiv(elements_i64 * IntImm(DataType::Int(64), bits) +
63	                      IntImm(DataType::Int(64), 7),
64	                  IntImm(DataType::Int(64), 8));
